// Bridging on the simulated club: does an idea pushed by one faction get held back, and does a broadly wanted idea
// still go through? No model: the ideas are the simulation's own (each its true cluster), so only the bridging step
// is measured. Simulated club: members and requests generated by code (test/sim/loop_club.mjs).
//   The club of each seed, plus a faction: 12 members (6 who play on weekdays, 6 at weekends, so the old two-group rule
//   lets them through) who all share two pet ideas and put their votes on them. Everyone else votes as in loop_eval.
//   Then, for every idea: its members, the old score (2 per unmet, 1 per wish, plus raw votes), the bridging intercept
//   and factor (proposals.bridgeScores), the cluster-matched votes, and whether each rule lets it through.
//   node test/loop_bridge_eval.mjs [data/loop_bridge_eval.json] [--seeds 7,11,13]
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const args = process.argv.slice(2), opt = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
const OUT = args.find((a) => /\.json$/.test(a)) || "data/loop_bridge_eval.json", SEEDS = opt("--seeds", "7,11,13").split(",").map(Number);
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "serve-bridge-"));
Object.assign(process.env, { LOOP_DIR: `${tmp}/loop`, STORE_FILE: `${tmp}/players.json`, LEDGER_FILE: `${tmp}/ledger.jsonl` });
const { rng, simClub } = await import("./sim/loop_club.mjs");
const proposals = await import("../src/loop/proposals.js");
const T0 = Date.UTC(2026, 8, 7, 4, 0);
const out = { label: "Simulated club: members and requests generated by code. The bridging is the code the loop runs.", at: new Date().toISOString(), seeds: {} };
for (const seed of SEEDS) {
  const R = rng(seed * 7919 + 1), { people, normal, supports, shuffle, pick } = simClub({ seed, members: 60, R, T0 });
  // the faction: 12 normal members, half weekday and half weekend players, two pet ideas, all their votes on them
  const fac = [...shuffle(normal.filter((p) => p.group === "weekday")).slice(0, 6), ...shuffle(normal.filter((p) => p.group === "weekend")).slice(0, 6)];
  const support = new Map(); // idea -> Map(who -> kind)
  const add = (idea, who, kind) => { if (!support.has(idea)) support.set(idea, new Map()); const m = support.get(idea); m.set(who, m.get(who) === "unmet" || kind === "unmet" ? "unmet" : "wish"); };
  for (const s of supports) if (!s.hostile && s.yes && (s.kind === "wish" || s.p.consent)) add(s.idea, s.p.id, s.kind);
  for (const p of fac) { add("faction1", p.id, "wish"); add("faction2", p.id, "wish"); }
  const ideas = [...support.keys()].filter((k) => support.get(k).size >= 2), votes = new Map(ideas.map((k) => [k, new Map()]));
  for (const p of people.filter((x) => x.consent && !x.hostile)) {
    if (fac.includes(p)) { votes.get("faction1").set(p.id, 2); votes.get("faction2").set(p.id, 2); continue; }
    if (R() < 0.5) continue;
    const mine = ideas.filter((k) => support.get(k).has(p.id)), other = ideas.filter((k) => !mine.includes(k));
    if (mine[0]) votes.get(mine[0]).set(p.id, 2);
    if (other.length) { const k = pick(other); votes.get(k).set(p.id, (votes.get(k).get(p.id) || 0) + 1); }
  }
  // the ratings: every member who took part, against every idea
  const raters = new Set([...[...support.values()].flatMap((m) => [...m.keys()]), ...[...votes.values()].flatMap((m) => [...m.keys()])]);
  const ratings = [];
  for (const who of raters) for (const k of ideas) ratings.push({ who, item: k, r: support.get(k).has(who) || votes.get(k).has(who) ? 1 : 0 });
  // what the loop runs (proposals.bridging): backers are those who shared a request in the idea or voted for it
  const br = proposals.bridging(new Map(ideas.map((k) => [k, new Set([...support.get(k).keys(), ...votes.get(k).keys()])]))), side = (who) => br.sides[who] ?? null;
  const rows = ideas.map((k) => {
    const m = support.get(k), unmet = [...m.values()].filter((x) => x === "unmet").length, raw = [...votes.get(k).values()].reduce((a, b) => a + b, 0), matched = proposals.matchedVotes(votes.get(k), side);
    const groups = new Set([...m.keys()].map((w) => people.find((p) => p.id === w)?.group));
    return { idea: k, members: m.size, unmet, wishes: m.size - unmet, votes: raw, matchedVotes: +matched.toFixed(1), oldScore: unmet * 2 + (m.size - unmet) + raw, newScore: +(unmet * 2 + (m.size - unmet) + matched).toFixed(1),
      intercept: br.byIdea.get(k).intercept, factor: br.byIdea.get(k).factor, together: br.byIdea.get(k).together, bothDays: groups.has("weekday") && groups.has("weekend"),
      oldGate: m.size >= 5 && groups.has("weekday") && groups.has("weekend"), ...(() => { const x = proposals.bridgedBy([...m.keys()], side); return { sideRule: x.bridged, outside: x.outside, sides: x.sides }; })(), bridged: !br.byIdea.get(k).oneSided, factorOnly: Math.abs(br.byIdea.get(k).factor) < proposals.FACTOR_MAX() };
  });
  rows.forEach((r) => { r.newGate = r.oldGate && r.bridged; r.sideGate = r.oldGate && r.sideRule; r.factorGate = r.oldGate && r.factorOnly; });
  const rankOld = [...rows].sort((a, b) => b.oldScore - a.oldScore).map((r) => r.idea), rankNew = [...rows].filter((r) => r.newGate).sort((a, b) => b.newScore - a.newScore).map((r) => r.idea);
  out.seeds[seed] = { raters: raters.size, faction: fac.length, rows: rows.sort((a, b) => b.oldScore - a.oldScore), rankOld, rankNew,
    factionThroughOld: rows.filter((r) => /^faction/.test(r.idea) && r.oldGate).length, factionThroughNew: rows.filter((r) => /^faction/.test(r.idea) && r.newGate).length,
    factionThroughFactorOnly: rows.filter((r) => /^faction/.test(r.idea) && r.factorGate).length, broadThroughFactorOnly: rows.filter((r) => !/^faction/.test(r.idea) && r.factorGate).map((r) => r.idea),
    factionThroughSideRule: rows.filter((r) => /^faction/.test(r.idea) && r.sideGate).length, broadThroughSideRule: rows.filter((r) => !/^faction/.test(r.idea) && r.sideGate).map((r) => r.idea),
    broadThroughOld: rows.filter((r) => !/^faction/.test(r.idea) && r.oldGate).map((r) => r.idea), broadThroughNew: rows.filter((r) => !/^faction/.test(r.idea) && r.newGate).map((r) => r.idea) };
  console.log(`seed ${seed}: raters ${raters.size}`);
  for (const r of out.seeds[seed].rows) console.log(`  ${r.idea.padEnd(9)} members ${String(r.members).padStart(2)} votes ${String(r.votes).padStart(2)} → matched ${String(r.matchedVotes).padStart(4)}  b ${r.intercept.toFixed(3).padStart(6)} f ${r.factor.toFixed(3).padStart(6)} together ${r.together} sides +${r.sides["+"]}/-${r.sides["-"]}/0:${r.sides.none} side rule ${r.sideRule ? "y" : "n"}  old ${r.oldGate ? "through" : "-"}  new ${r.newGate ? "through" : "-"}`);
  console.log(`  ranked, old: ${rankOld.join(" > ")}\n  ranked, new: ${rankNew.join(" > ")}`);
}
// and the loop_eval run's own data (no faction in it): which of its ideas each rule would hold back
const STATE = opt("--state", null);
if (STATE) {
  const st = JSON.parse(fs.readFileSync(path.join(STATE, "ideas.json"), "utf8")), items = new Map(JSON.parse(fs.readFileSync(path.join(STATE, "signals.json"), "utf8")).items.map((x) => [x.id, x]));
  const votes = new Map(); for (const m of Object.values(st.votes || {})) for (const [who, mine] of Object.entries(m)) for (const p of Object.keys(mine)) { if (!votes.has(p)) votes.set(p, new Set()); votes.get(p).add(who); }
  const cols = st.clusters.filter((c) => c.items.length >= 2 || c.proposal), backers = new Map(cols.map((c) => [c.id, new Set([...c.items.map((id) => items.get(id)?.who).filter(Boolean), ...(c.proposal ? [...(votes.get(c.proposal) || [])] : [])])]));
  const br = proposals.bridging(backers);
  out.loopEval = { raters: br.raters, ideas: cols.filter((c) => c.members >= 5).map((c) => ({ id: c.id, text: c.text, members: c.members, ...br.byIdea.get(c.id), factorOnlyHolds: Math.abs(br.byIdea.get(c.id)?.factor ?? 0) >= proposals.FACTOR_MAX() })) };
  console.log("loop_eval's ideas:", JSON.stringify(out.loopEval, null, 1));
}
fs.writeFileSync(OUT, JSON.stringify(out, null, 1));
console.log(`written ${OUT}`);
